def test_too_many_turns_is_inconclusive_not_failed() -> None:
    """A model that flailed for 13 turns did not disprove the docstring; it ran out of room."""
    events = transcript.read_events(FIXTURE)
    events[-1]["num_turns"] = 13

    reason = selfcheck.inconclusive_reason(transcript.from_events(events))

    assert reason is not None and "13" in reason


def test_an_errored_result_is_inconclusive() -> None:
    events = transcript.read_events(FIXTURE)
    events[-1] |= {"subtype": "error_during_execution", "is_error": True}

    assert selfcheck.inconclusive_reason(transcript.from_events(events)) is not None


def test_inconclusive_is_not_broken() -> None:
    """The distinction is the whole point: a timeout is not evidence of a harness fault."""
    events = transcript.read_events(FIXTURE)
    events[-1]["num_turns"] = 13

    selfcheck.verify(transcript.from_events(events), cwd=CWD)
